"use client";

import * as THREE from "three";
import React from "react";
import { useGLTF, Outlines } from "@react-three/drei";
import { GLTF } from "three-stdlib";

const HIDDEN_OBJECTS = ["bedOn", "cup"];

type GLTFResult = GLTF & {
  nodes: { [key: string]: THREE.Mesh };
  materials: { [key: string]: THREE.MeshStandardMaterial };
};

const ROOM_DATA_URL =
  "data:model/gltf-binary;base64," +
  "";

export default function Room(props: React.JSX.IntrinsicElements["group"]) {
  // const { nodes } = useGLTF("./room-transformed.glb") as unknown as GLTFResult;
  const { nodes } = useGLTF(ROOM_DATA_URL) as unknown as GLTFResult;

  return (
    <group {...props} dispose={null}>
      {Object.entries(nodes).map(([name, node]) => {
        if (!node.isMesh) return null;

        console.log("オブジェクト名:", name);

        if (HIDDEN_OBJECTS.includes(name)) {
          return null;
        }

        return (
          <mesh
            key={name}
            name={name}
            // ★ visibleを使うならここに書く
            // visible={!isHidden}
            geometry={node.geometry}
            position={node.position}
            rotation={node.rotation}
            scale={node.scale}
            castShadow
            receiveShadow
          >
            <meshToonMaterial
              color={(node.material as THREE.MeshStandardMaterial).color}
              map={(node.material as THREE.MeshStandardMaterial).map}
            />
          </mesh>
        );
      })}
    </group>
  );
}

// useGLTF.preload("/room-transformed.glb");
useGLTF.preload(ROOM_DATA_URL);
